(async () => { window.THREE = await import('three');
window.G3reach = (id, side = 0, w = 1, up = -1.25, el = -0.25, dur = 0.6) => {
  const c = id === 'kai' ? __game.player.char : __game.actors[id]; if (!c) return 'no ' + id;
  const T = window.THREE;
  if (!c.__reach) {
    const orig = c.update3d; c.__reach = { w: 0, to: 0, side, up, el, dur, yaw: 0 };
    const q = new T.Quaternion(), q2 = new T.Quaternion(), v = new T.Vector3();
    c.update3d = function (dt) {
      orig.call(this, dt);
      const R = this.__reach; if (dt > 0) R.w += Math.sign(R.to - R.w) * Math.min(Math.abs(R.to - R.w), dt / R.dur);
      if (R.w <= 1e-3) return;
      const s = R.w * R.w * (3 - 2 * R.w);
      const a = this.arms[R.side].bone; if (!a.up || !a.el) return;
      const right = v.set(1, 0, 0).applyQuaternion(this.root.quaternion);
      for (const [b, ang] of [[a.up, R.up * s], [a.el, R.el * s]]) {
        b.getWorldQuaternion(q); q2.setFromAxisAngle(right, ang); q.premultiply(q2);
        b.parent.getWorldQuaternion(q2).invert(); b.quaternion.copy(q2.multiply(q)); b.updateMatrixWorld(true);
      }
    };
  }
  Object.assign(c.__reach, { to: w, side, up, el, dur });
  return c.__reach;
};

window.G3frags = (avoid, frames = 140, seed = 7, minR = 0) => {
  const T = window.THREE, ch = __game.scene.children.find(o => o.userData && o.userData.frags);
  const F = ch.userData.frags; ch.updateMatrixWorld(true);
  let s = seed >>> 0; const rnd = () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
  const pts = avoid.map(a => ({ p: new T.Vector3(...a.p), q: a.q ? new T.Vector3(...a.q) : null, r: a.r }));
  const segD = (v, a) => { if (!a.q) return v.distanceTo(a.p); const ab = a.q.clone().sub(a.p), t = Math.max(0, Math.min(1, v.clone().sub(a.p).dot(ab) / ab.lengthSq())); return v.distanceTo(a.p.clone().addScaledVector(ab, t)); };
  const out = [];
  F.children.forEach((f, i) => {
    const g = f.geometry.parameters, R = g.radius, arc = g.arc, e = new T.Euler(), m = new T.Matrix4(), v = new T.Vector3();
    let best = null;
    for (let tries = 0; tries < 400; tries++) {
      const rx = rnd() * 6.283, ry = rnd() * 6.283; let ok = true, mind = 1e9;
      for (let k = 0; k <= frames && ok; k += 3) {
        e.set(rx + 0.003 * (i + 1) * k, ry + 0.002 * (i + 1) * k, f.rotation.z);
        m.makeRotationFromEuler(e).premultiply(F.matrixWorld);
        for (let j = 0; j <= 24; j++) { const th = arc * j / 24; v.set(R * Math.cos(th), R * Math.sin(th), 0).applyMatrix4(m); for (const a of pts) { const d = segD(v, a) - a.r; if (d < mind) mind = d; if (d < 0) { ok = false; break; } } if (!ok) break; }
      }
      if (ok && mind >= minR) { best = [rx, ry, mind]; break; }
    }
    if (best) { f.rotation.x = best[0]; f.rotation.y = best[1]; out.push(+best[2].toFixed(2)); } else out.push('none');
  });
  return out;
};

return 'helpers'; })()

